import json,numpy as np
c0=json.load(open('/app/output/observations/initial/meta.json'))['cameras']['wrist_cam'];C0=np.array(c0['cam2world_gl']);K=np.array(c0['intrinsic_cv'])
def rq(q):
 w,x,y,z=q;return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def T(p,q):
 t=np.eye(4);t[:3,:3]=rq(q);t[:3,3]=p;return t
T0=T([.359703,0,.309767],[-.0000003,-.7071068,.7071069,.0000002]);Tc=T([.273957,.18915,.064286],[-.271052,-.655339,.651454,-.269573]);C=Tc@np.linalg.inv(T0)@C0; R=C[:3,:3]@np.diag([1,-1,-1]); cc=C[:3,3]
print('cam',cc)
def pj(p):
 cp=R.T@(np.array(p)-cc);v=K@cp;return np.round(v[:2]/v[2],1)
for name,p in [('eef',[.273957,.18915,.064286]),('cupcenter',[.275,.19,.06]),('cupcenter_z0.1',[.275,.19,.10]),('rim',[.275,.19,.14]),('bowl',[.36,-.24,.05]),('blue at init estimated',[.275,.19,.003])]:print(name,pj(p))
PY

